package com.thang.user.controller;
import com.thang.user.repository.AdminAccountAuditRepository;import com.nihongo.security.SafeCsv;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.http.*;import org.springframework.data.domain.PageRequest;import java.util.*;
@RestController @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')")
public class AccountAuditExportController {
 private final AdminAccountAuditRepository audit;
 @GetMapping("/api/users/admin/audit/export") public ResponseEntity<byte[]> export(@RequestParam(required=false) java.time.LocalDate from,@RequestParam(required=false) java.time.LocalDate to){var dates=com.nihongo.security.CsvDates.validate(from,to);var records=audit.findByCreatedAtGreaterThanEqualAndCreatedAtLessThanOrderByCreatedAtDescIdDesc(dates.from().atStartOfDay(),dates.to().plusDays(1).atStartOfDay(),PageRequest.of(0,10000));if(records.getTotalElements()>10000)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Nhật ký vượt 10000 dòng; cần xuất theo khoảng ngày nhỏ hơn");var rows=records.getContent().stream().map(a->Arrays.asList(a.getCreatedAt(),a.getActorUserId(),a.getAction(),a.getTargetUserId(),a.getOldValue(),a.getNewValue())).toList();return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=account-audit.csv").contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).body(SafeCsv.write(List.of("Thời gian","Người thao tác","Hành động","Tài khoản","Trước","Sau"),rows));}
}
